
local dtx=[==[]==]
local uow=
(function(...)
local unb={169,61,23,184,181,15,10,108,13,173,44,156,29,217,24,183,162,122,151,4}
local qply=bit32 or bit
local hu=qply.bxor
for uqlt=1,#unb do unb[uqlt]=hu(unb[uqlt],(18*uqlt+8)%256) end
local cx="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local xlh={}
for lqlqh=1,#cx do xlh[cx:byte(lqlqh)]=lqlqh-1 end
local function tgbam(str)
  local R={} local acc,nb=0,0
  for edyr=1,#str do
    local v=xlh[str:byte(edyr)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function sxwis(key,data)
  local S={} for gtg=0,255 do S[gtg]=gtg end
  local j=0
  for yprxp=0,255 do
    j=(j+S[yprxp]+key[(yprxp%#key)+1])%256
    S[yprxp],S[j]=S[j],S[yprxp]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(hu(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=sxwis(unb,tgbam(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local xk=nf()
return function(big) return xk(big) end
end)(...)

return uow(dtx)
